dding the pattern.","formation":"Quantity + ずつ","difficulty":"Core","examples":[{"japanese":"学生に二枚ずつ配りました。","romaji":"Gakusei ni nimai zutsu kubarimashita.","meaning":"I distributed two sheets to each student."}],"common_mistakes":["Do not substitute a nearby expression with a different nuance. Build the verb or clause first, then attach Quantity + ずつ as shown in Quantity + ずつ."],"practice_questions":[{"id":"n4-98-meaning","prompt":"What does “Quantity + ずつ” mean?","options":["Have to","Do not have to","Each / at a time","Must / have to"],"answer":"Each / at a time","explanation":"Quantity + ずつ expresses each / at a time. Use this construction to connect the stated action, condition or viewpoint to the rest of the sentence. Check the required plain, て, た or negative form before adding the pattern."},{"id":"n4-98-formation","prompt":"Choose the correct formation for “Each ずつ”.","options":["ない-form + といけない","Quantity + ずつ","ない-form without い + なければならない","ない-form without い + なくてはいけない"],"answer":"Quantity + ずつ","explanation":"Quantity + ずつ expresses each / at a time. Use this construction to connect the stated action, condition or viewpoint to the rest of the sentence. Check the required plain, て, た or negative form before adding the pattern."},{"id":"n4-98-example","prompt":"Which sentence illustrates “Each ずつ”?","options":["学生に二枚ずつ配りました。","毎日薬を飲まなければなりません。","宿題をしなくてはいけません。","もう帰らないといけません。"],"answer":"学生に二枚ずつ配りました。","explanation":"学生に二枚ずつ配りました。 (Gakusei ni nimai zutsu kubarimashita.) means “I distributed two sheets to each student.”."},{"id":"n4-98-translation","prompt":"Choose the meaning of: 学生に二枚ずつ配りました。","options":["I must take medicine every day.","I have to do my homework.","I have to go home now.","I distributed two sheets to each student."],"answer":"I distributed two sheets to each student.","explanation":"学生に二枚ずつ配りました。 (Gakusei ni nimai zutsu kubarimashita.) means “I distributed two sheets to each student.”."}]},{"jlpt_level":"N4","sort_order":99,"category":"Source","title":"According to によると","pattern":"Source + によると","meaning":"According to","explanation":"Source + によると expresses according to. Use this construction to connect the stated action, condition or viewpoint to the rest of the sentence. Check the required plain, て, た or negative form before adding the pattern.","formation":"Source + によると + report","difficulty":"Core","examples":[{"japanese":"天気予報によると明日は晴れるそうです。","romaji":"Tenki yohou ni yoru to ashita wa hareru sou desu.","meaning":"According to the forecast, it will be sunny tomorrow."}],"common_mistakes":["Do not substitute a nearby expression with a different nuance. Build the verb or clause first, then attach Source + によると as shown in Source + によると + report."],"practice_questions":[{"id":"n4-99-meaning","prompt":"What does “Source + によると” mean?","options":["Do not have to","According to","Must / have to","Have to"],"answer":"According to","explanation":"Source + によると expresses according to. Use this construction to connect the stated action, condition or viewpoint to the rest of the sentence. Check the required plain, て, た or negative form before adding the pattern."},{"id":"n4-99-formation","prompt":"Choose the correct formation for “According to によると”.","options":["Source + によると + report","ない-form without い + なければならない","ない-form without い + なくてはいけない","ない-form + といけない"],"answer":"Source + によると + report","explanation":"Source + によると expresses according to. Use this construction to connect the stated action, condition or viewpoint to the rest of the sentence. Check the required plain, て, た or negative form before adding the pattern."},{"id":"n4-99-example","prompt":"Which sentence illustrates “According to によると”?","options":["毎日薬を飲まなければなりません。","宿題をしなくてはいけません。","もう帰らないといけません。","天気予報によると明日は晴れるそうです。"],"answer":"天気予報によると明日は晴れるそうです。","explanation":"天気予報によると明日は晴れるそうです。 (Tenki yohou ni yoru to ashita wa hareru sou desu.) means “According to the forecast, it will be sunny tomorrow.”."},{"id":"n4-99-translation","prompt":"Choose the meaning of: 天気予報によると明日は晴れるそうです。","options":["I have to do my homework.","I have to go home now.","According to the forecast, it will be sunny tomorrow.","I must take medicine every day."],"answer":"According to the forecast, it will be sunny tomorrow.","explanation":"天気予報によると明日は晴れるそうです。 (Tenki yohou ni yoru to ashita wa hareru sou desu.) means “According to the forecast, it will be sunny tomorrow.”."}]},{"jlpt_level":"N4","sort_order":100,"category":"Topic","title":"About について","pattern":"Noun + について","meaning":"About / concerning","explanation":"Noun + について expresses about / concerning. Use this construction to connect the stated action, condition or viewpoint to the rest of the sentence. Check the required plain, て, た or negative form before adding the pattern.","formation":"Noun + について + verb","difficulty":"Core","examples":[{"japanese":"日本の文化について話しました。","romaji":"Nihon no bunka ni tsuite hanashimashita.","meaning":"We talked about Japanese culture."}],"common_mistakes":["Do not substitute a nearby expression with a different nuance. Build the verb or clause first, then attach Noun + について as shown in Noun + について + verb."],"practice_questions":[{"id":"n4-100-meaning","prompt":"What does “Noun + について” mean?","options":["About / concerning","Must / have to","Have to","Do not have to"],"answer":"About / concerning","explanation":"Noun + について expresses about / concerning. Use this construction to connect the stated action, condition or viewpoint to the rest of the sentence. Check the required plain, て, た or negative form before adding the pattern."},{"id":"n4-100-formation","prompt":"Choose the correct formation for “About について”.","options":["ない-form without い + なければならない","ない-form without い + なくてはいけない","ない-form + といけない","Noun + について + verb"],"answer":"Noun + について + verb","explanation":"Noun + について expresses about / concerning. Use this construction to connect the stated action, condition or viewpoint to the rest of the sentence. Check the required plain, て, た or negative form before adding the pattern."},{"id":"n4-100-example","prompt":"Which sentence illustrates “About について”?","options":["宿題をしなくてはいけません。","もう帰らないといけません。","日本の文化について話しました。","毎日薬を飲まなければなりません。"],"answer":"日本の文化について話しました。","explanation":"日本の文化について話しました。 (Nihon no bunka ni tsuite hanashimashita.) means “We talked about Japanese culture.”."},{"id":"n4-100-translation","prompt":"Choose the meaning of: 日本の文化について話しました。","options":["I have to go home now.","We talked about Japanese culture.","I must take medicine every day.","I have to do my homework."],"answer":"We talked about Japanese culture.","explanation":"日本の文化について話しました。 (Nihon no bunka ni tsuite hanashimashita.) means “We talked about Japanese culture.”."}]}]$n4_json$::jsonb;
begin
 insert into public.grammar_points(jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,category,difficulty,sort_order,meaning,practice_questions,publication_status)
 select 'N4'::public.jlpt_level,r.title,r.pattern,r.explanation,r.formation,r.examples,r.common_mistakes,r.category,r.difficulty,r.sort_order,r.meaning,r.practice_questions,'published'::public.publication_status
 from jsonb_to_recordset(v_data) as r(sort_order integer,category text,title text,pattern text,meaning text,explanation text,formation text,difficulty text,examples jsonb,common_mistakes jsonb,practice_questions jsonb,jlpt_level text)
 on conflict(jlpt_level,pattern) do update set title=excluded.title,meaning=excluded.meaning,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,category=excluded.category,difficulty=excluded.difficulty,sort_order=excluded.sort_order,practice_questions=excluded.practice_questions,publication_status='published',updated_at=now();
end;
